import json

def backtrack(a,b,ge=True,prefer_minus=True,sentinel=True):
    aa=list(a)+([None] if sentinel else []); bb=list(b)+([None] if sentinel else [])
    n,m=len(aa),len(bb); C=[[0]*(m+1) for _ in range(n+1)]
    for i,tv in enumerate(aa):
        for j,uv in enumerate(bb):
            C[i+1][j+1]=C[i][j]+1 if tv==uv else max(C[i][j+1],C[i+1][j])
    ma=[False]*n; mb=[False]*m; i=n;j=m
    while i>0 and j>0:
        if aa[i-1]==bb[j-1]: ma[i-1]=mb[j-1]=True;i-=1;j-=1
        else:
            # decide skip minus if condition
            if prefer_minus:
                cond=C[i-1][j]>=C[i][j-1] if ge else C[i-1][j]>C[i][j-1]
                if cond: i-=1
                else: j-=1
            else:
                cond=C[i][j-1]>=C[i-1][j] if ge else C[i][j-1]>C[i-1][j]
                if cond: j-=1
                else: i-=1
    return fmt(ma,len(a)),fmt(mb,len(b))
def fmt(x,n): return ''.join('C' if z else 'U' for z in x[:n])
def forward_suffix(a,b,ge=True,prefer_minus=True,sentinel=True):
    aa=list(a)+([None] if sentinel else []); bb=list(b)+([None] if sentinel else [])
    n,m=len(aa),len(bb); S=[[0]*(m+1) for _ in range(n+1)]
    for i in range(n-1,-1,-1):
        for j in range(m-1,-1,-1): S[i][j]=S[i+1][j+1]+1 if aa[i]==bb[j] else max(S[i+1][j],S[i][j+1])
    ma=[False]*n;mb=[False]*m;i=j=0
    while i<n and j<m:
        if aa[i]==bb[j]: ma[i]=mb[j]=True;i+=1;j+=1
        else:
            if prefer_minus:
                cond=S[i+1][j]>=S[i][j+1] if ge else S[i+1][j]>S[i][j+1]
                if cond: i+=1
                else: j+=1
            else:
                cond=S[i][j+1]>=S[i+1][j] if ge else S[i][j+1]>S[i+1][j]
                if cond: j+=1
                else: i+=1
    return fmt(ma,len(a)),fmt(mb,len(b))

def gestalt(a,b,tie='ab',sentinel=True):
    aa=list(a)+([None] if sentinel else []); bb=list(b)+([None] if sentinel else [])
    ma=[False]*len(aa); mb=[False]*len(bb)
    def longest(i1,i2,j1,j2):
        best=(0,i1,j1) # len,i,j
        # find longest common contiguous block. Use DP ending at i,j scanning according tie order.
        # brute all starts and length, order starts by i then j or j then i. Max only replace if >.
        starts=[]
        if tie in ('ab','ba-len-first'):
            starts=[(i,j) for i in range(i1,i2) for j in range(j1,j2)]
            if tie=='ba-len-first': starts=[(i,j) for j in range(j1,j2) for i in range(i1,i2)]
        for i,j in starts:
            l=0
            while i+l<i2 and j+l<j2 and aa[i+l]==bb[j+l]: l+=1
            if l>best[0]: best=(l,i,j)
        return best
    def rec(i1,i2,j1,j2):
        l,i,j=longest(i1,i2,j1,j2)
        if l==0: return
        for k in range(l): ma[i+k]=mb[j+k]=True
        rec(i1,i,j1,j); rec(i+l,i2,j+l,j2)
    rec(0,len(aa),0,len(bb))
    return fmt(ma,len(a)),fmt(mb,len(b))

def score(fn,data):
    f=0; ex=[]
    for a,b,obs in data:
        pred=fn(a,b)
        if list(pred)!=obs: 
            f+=1
            if len(ex)<5:ex.append((a,b,obs,pred))
    return f,ex

