import json

def myers(a,b,prefer_down=True,sentinel=True,swap=False):
    # returns matched masks original orientation. If swap, compute b vs a then swap outputs.
    aa=list(b if swap else a); bb=list(a if swap else b)
    if sentinel: aa=aa+[None]; bb=bb+[None]
    n=len(aa); m=len(bb); maxd=n+m
    # V offset maxd
    v={1:0}
    trace=[]
    found=None
    for d in range(maxd+1):
        trace.append(dict(v))
        for k in range(-d,d+1,2):
            if k==-d or (k!=d and (v.get(k-1,0) < v.get(k+1,0) if prefer_down else v.get(k-1,0) > v.get(k+1,0))):
                x=v.get(k+1,0) # down (insertion in aa direction)
            else:
                x=v.get(k-1,0)+1 # right (deletion)
            y=x-k
            while x<n and y<m and aa[x]==bb[y]: x+=1; y+=1
            v[k]=x
            if x>=n and y>=m:
                found=d; break
        if found is not None: break
    # backtrack
    ma=[False]*n; mb=[False]*m
    x=n; y=m
    for d in range(found,0,-1):
        vprev=trace[d]  # trace[d] corresponds V before iteration d? We appended at beginning of d loop, so trace[d] is V_{d-1}; caveat index list len.
        k=x-y
        # determine prev k based on same preference rule used
        if k==-d or (k!=d and (vprev.get(k-1,0) < vprev.get(k+1,0) if prefer_down else vprev.get(k-1,0) > vprev.get(k+1,0))):
            prev_k=k+1
        else:
            prev_k=k-1
        prev_x=vprev.get(prev_k,0); prev_y=prev_x-prev_k
        while x>prev_x and y>prev_y:
            ma[x-1]=mb[y-1]=True; x-=1; y-=1
        if d>0:
            if x==prev_x: y-=1 # down
            else: x-=1 # right
    while x>0 and y>0:
        ma[x-1]=mb[y-1]=True; x-=1;y-=1
    A=''.join('C' if z else 'U' for z in ma[:len(aa)-(1 if sentinel else 0)])
    B=''.join('C' if z else 'U' for z in mb[:len(bb)-(1 if sentinel else 0)])
    return (B,A) if swap else (A,B)

