import json

def lcs_row(a,b):
    # returns list len(b)+1: LCS lengths a vs each prefix b[:j]
    prev=[0]*(len(b)+1); cur=[0]*(len(b)+1)
    for x in a:
        cur[0]=0
        for j,y in enumerate(b,1):
            cur[j]=prev[j-1]+1 if x==y else max(prev[j],cur[j-1])
        prev,cur=cur,prev
    return prev

def hirsch(a,b,tie='first',base='first',sentinel=True,split_axis='a'):
    aa=list(a)+([None] if sentinel else []); bb=list(b)+([None] if sentinel else [])
    ma=[False]*len(aa); mb=[False]*len(bb)
    def rec(i1,i2,j1,j2):
        # ranges aa[i1:i2], bb[j1:j2]
        if i1>=i2 or j1>=j2: return
        if split_axis=='a' or (split_axis=='longer' and (i2-i1)>=(j2-j1)) or (split_axis=='shorter' and (i2-i1)<=(j2-j1)):
            if i2-i1==1:
                rng=range(j1,j2) if base=='first' else range(j2-1,j1-1,-1)
                for j in rng:
                    if aa[i1]==bb[j]: ma[i1]=mb[j]=True; break
                return
            mid=(i1+i2)//2
            l1=lcs_row(aa[i1:mid],bb[j1:j2])
            # reverse second half vs reverse suffixes: row for reversed(aa[mid:i2]) vs reversed(bb[j1:j2]), then suffix starting k corresponds prefix ending...
            l2=lcs_row(aa[mid:i2][::-1],bb[j1:j2][::-1])
            best=-1; bestk=j1
            for off in range(0,(j2-j1)+1):
                val=l1[off]+l2[(j2-j1)-off]
                if val>best or (tie=='last' and val==best): best=val;bestk=j1+off
            rec(i1,mid,j1,bestk); rec(mid,i2,bestk,j2)
        else:
            # split bb symmetrically, swapping roles
            if j2-j1==1:
                rng=range(i1,i2) if base=='first' else range(i2-1,i1-1,-1)
                for i in rng:
                    if aa[i]==bb[j1]: ma[i]=mb[j1]=True;break
                return
            mid=(j1+j2)//2
            l1=lcs_row(bb[j1:mid],aa[i1:i2])
            l2=lcs_row(bb[mid:j2][::-1],aa[i1:i2][::-1])
            best=-1;bestk=i1
            for off in range(0,(i2-i1)+1):
                val=l1[off]+l2[(i2-i1)-off]
                if val>best or (tie=='last' and val==best):best=val;bestk=i1+off
            rec(i1,bestk,j1,mid); rec(bestk,i2,mid,j2)
    rec(0,len(aa),0,len(bb))
    return ''.join('C' if x else 'U' for x in ma[:len(a)]),''.join('C' if x else 'U' for x in mb[:len(b)])

data=json.load(open('/tmp/lcsdata.json'))
for axis in ['a','b','longer','shorter']:
 for tie in ['first','last']:
  for base in ['first','last']:
   for sentinel in [True,False]:
    fails=0;ex=[]
    for a,b,obs in data:
      pred=hirsch(a,b,tie,base,sentinel,axis)
      if list(pred)!=obs:fails+=1; ex.append((a,b,obs,pred)) if len(ex)<2 else None
    print(axis,tie,base,sentinel,fails,ex)
