import json,itertools

def fmt(m,n): return ''.join('C' if x else 'U' for x in m[:n])
def back_policy(a,b,order,sentinel=True):
 aa=list(a)+([None] if sentinel else []);bb=list(b)+([None] if sentinel else []);n=len(aa);m=len(bb)
 C=[[0]*(m+1) for _ in range(n+1)]
 for i in range(n):
  for j in range(m): C[i+1][j+1]=C[i][j]+1 if aa[i]==bb[j] else max(C[i][j+1],C[i+1][j])
 ma=[False]*n;mb=[False]*m;i=n;j=m
 while i>0 and j>0:
  acted=False
  for act in order:
   if act=='D' and aa[i-1]==bb[j-1]: ma[i-1]=mb[j-1]=True;i-=1;j-=1;acted=True;break
   if act=='U' and C[i][j]==C[i-1][j]: i-=1;acted=True;break
   if act=='L' and C[i][j]==C[i][j-1]: j-=1;acted=True;break
  if not acted:
   # fallback diag if equal else choose larger neighbor (ge minus)
   if aa[i-1]==bb[j-1]: ma[i-1]=mb[j-1]=True;i-=1;j-=1
   elif C[i-1][j]>=C[i][j-1]: i-=1
   else:j-=1
 return fmt(ma,len(a)),fmt(mb,len(b))

def fwd_policy(a,b,order,sentinel=True):
 aa=list(a)+([None] if sentinel else []);bb=list(b)+([None] if sentinel else []);n=len(aa);m=len(bb)
 S=[[0]*(m+1) for _ in range(n+1)]
 for i in range(n-1,-1,-1):
  for j in range(m-1,-1,-1):S[i][j]=S[i+1][j+1]+1 if aa[i]==bb[j] else max(S[i+1][j],S[i][j+1])
 ma=[False]*n;mb=[False]*m;i=j=0
 while i<n and j<m:
  acted=False
  for act in order:
   if act=='D' and aa[i]==bb[j]:ma[i]=mb[j]=True;i+=1;j+=1;acted=True;break
   if act=='U' and S[i][j]==S[i+1][j]:i+=1;acted=True;break
   if act=='L' and S[i][j]==S[i][j+1]:j+=1;acted=True;break
  if not acted:
   if aa[i]==bb[j]:ma[i]=mb[j]=True;i+=1;j+=1
   elif S[i+1][j]>=S[i][j+1]:i+=1
   else:j+=1
 return fmt(ma,len(a)),fmt(mb,len(b))

data=json.load(open('/tmp/lcsdata.json'))
for sentinel in [True,False]:
 for order in itertools.permutations('DUL'):
  for name,fn in [('back',back_policy),('fwd',fwd_policy)]:
   fails=sum(list(fn(a,b,order,sentinel))!=obs for a,b,obs in data)
   print(name,''.join(order),sentinel,fails)
