import json,bisect

def lis_simple(a,b,occ='desc',bound='lower',sentinel=True,swap=False,reconstruct='tails'):
 aa=list(b if swap else a);bb=list(a if swap else b)
 if sentinel:aa+=[None];bb+=[None]
 pos={}
 for j,t in enumerate(bb):pos.setdefault(t,[]).append(j)
 seq=[]
 for i,t in enumerate(aa):
  lst=pos.get(t,[]); lst=lst[::-1] if occ=='desc' else lst
  for j in lst:seq.append((j,i))
 tails=[];tid=[];prev=[-1]*len(seq); parent_tid_at_pos=[]
 for idx,(x,ai) in enumerate(seq):
  p=bisect.bisect_left(tails,x) if bound=='lower' else bisect.bisect_right(tails,x)
  if p>0:prev[idx]=tid[p-1]
  if p==len(tails):tails.append(x);tid.append(idx)
  else:tails[p]=x;tid[p]=idx
 ma=[False]*len(aa);mb=[False]*len(bb)
 if reconstruct=='tails':
  chosen=tid
 else:
  chosen=[];cur=tid[-1] if tid else -1
  while cur!=-1:chosen.append(cur);cur=prev[cur]
 for idx in chosen:
  j,i=seq[idx];ma[i]=mb[j]=True
 A=''.join('C' if x else 'U' for x in ma[:len(b if swap else a)]);B=''.join('C' if x else 'U' for x in mb[:len(a if swap else b)])
 return (B,A) if swap else (A,B)
# quick repeated
for rec in ['tails','parent']:
 print(rec,lis_simple('!@!@!@!@','#@#@#@#@',reconstruct=rec))
data=json.load(open('/tmp/lcsdata.json'))
for swap in [0,1]:
 for occ in ['desc','asc']:
  for bound in ['lower','upper']:
   for rec in ['tails','parent']:
    fails=sum(list(lis_simple(a,b,occ,bound,True,swap,rec))!=obs for a,b,obs in data)
    print(swap,occ,bound,rec,fails)
