 'lexA_max':lambda p:max([tuple(x for x,y in q) for q in p]),
 'lexB_min':lambda p:min([tuple(y for x,y in q) for q in p],key=lambda z:z),
 'lexB_max':lambda p:max([tuple(y for x,y in q) for q in p]),
 'pairs_lex_min':lambda p:min(p),
 'pairs_lex_max':lambda p:max(p),
 'sum_absdiff_min':lambda p:min(sum(abs(x-y) for x,y in q) for q in p),
 'sum_absdiff_max':lambda p:max(sum(abs(x-y) for x,y in q) for q in p),
 'sum_i_min':lambda p:min(sum(x for x,y in q) for q in p),
 'sum_i_max':lambda p:max(sum(x for x,y in q) for q in p),
 'sum_j_min':lambda p:min(sum(y for x,y in q) for q in p),
 'sum_j_max':lambda p:max(sum(y for x,y in q) for q in p),
 'maxgap_min':lambda p:min(max([0]+[p[k+1][0]-p[k][0] for k in range(len(p)-1)]) for p in p),
}
# For scalar metrics we check if obs attains optimum (any optimal alignment)
data=json.load(open('/tmp/unique.json'))
counts={k:0 for k in metrics}; total=0; notopt=0; notin=0
examples={}
for a,b,obs in data:
 op=obs_pairs(a,b,obs); allp,opt=all_opt(a,b)
 if len(op)!=opt:notopt+=1;continue
 total+=1
 if op not in allp:notin+=1;continue
 # lex tuple metrics: determine target tuple/set
 # lex A min
 sets={}
 sets['lexA_min']={q for q in allp if tuple(x for x,y in q)==min(tuple(x for x,y in z) for z in allp)}
 sets['lexA_max']={q for q in allp if tuple(x for x,y in q)==max(tuple(x for x,y in z) for z in allp)}
 sets['lexB_min']={q for q in allp if tuple(y for x,y in q)==min(tuple(y for x,y in z) for z in allp)}
 sets['lexB_max']={q for q in allp if tuple(y for x,y in q)==max(tuple(y for x,y in z) for z in allp)}
 sets['pairs_lex_min']={min(allp)};sets['pairs_lex_max']={max(allp)}
 for name in ['sum_absdiff_min','sum_absdiff_max','sum_i_min','sum_i_max','sum_j_min','sum_j_max']:
  key={'sum_absdiff':lambda q:sum(abs(x-y) for x,y in q),'sum_i':lambda q:sum(x for x,y in q),'sum_j':lambda q:sum(y for x,y in q)}[name.rsplit('_',1)[0]]
  target=(min if name.endswith('_min') else max)(key(q) for q in allp);sets[name]={q for q in allp if key(q)==target}
 sets['maxgap_min']={q for q in allp if (max([0]+[q[k+1][0]-q[k][0] for k in range(len(q)-1)]) if q else 0)==min((max([0]+[z[k+1][0]-z[k][0] for k in range(len(z)-1)]) if z else 0) for z in allp)}
 for k,s in sets.items():
  if op in s:counts[k]+=1
print('total optimal',total,'notopt',notopt,'notin',notin)
print(counts)
