def all_opt(a,b):
 # include sentinel? Content alignments optimal LCS (without sentinel same)
 n,m=len(a),len(b)
 # suffix DP
 S=[[0]*(m+1) for _ in range(n+1)]
 for i in range(n-1,-1,-1):
  for j in range(m-1,-1,-1):S[i][j]=S[i+1][j+1]+1 if a[i]==b[j] else max(S[i+1][j],S[i][j+1])
 res=[]
 # generate match pair sequences via recursion choosing a match (i,j) such that a[i]==b[j] and S[i][j]==S[i+1][j+1]+1 and is optimal from state; also need ensure can skip to it while S[current]==S[i][j]
 def rec(i,j,cur):
  if S[i][j]==0:res.append(tuple(cur));return
  # choose next match p>=i,q>=j with a[p]==b[q], S[i][j]==S[p][q] (skipping doesn't hurt) and S[p][q]==S[p+1][q+1]+1
  opts=[]
  for p in range(i,n):
   for q in range(j,m):
    if a[p]==b[q] and S[i][j]==S[p][q] and S[p][q]==S[p+1][q+1]+1:opts.append((p,q))
  # To avoid duplicates due to multiple skip paths, generation by next match is unique.
  for p,q in opts:
   cur.append((p,q));rec(p+1,q+1,cur);cur.pop()
 rec(0,0,[])
 return res,S[0][0]

