import json,itertools

def walk(a,b,order,sentinel=True,fallback='geA'):
 aa=list(a)+([None] if sentinel else []);bb=list(b)+([None] if sentinel else []);n=len(aa);m=len(bb)
 C=[[0]*(m+1) for _ in range(n+1)]
 for i in range(n):
  for j in range(m):C[i+1][j+1]=C[i][j]+1 if aa[i]==bb[j] else max(C[i][j+1],C[i+1][j])
 ma=[False]*n;mb=[False]*m;i=j=0
 while i<n or j<m:
  acted=False
  for act in order:
   if act=='D' and i<n and j<m and aa[i]==bb[j] and C[i+1][j+1]==C[i][j]+1:ma[i]=mb[j]=True;i+=1;j+=1;acted=True;break
   if act=='A' and i<n and C[i+1][j]==C[i][j]:i+=1;acted=True;break
   if act=='B' and j<m and C[i][j+1]==C[i][j]:j+=1;acted=True;break
  if acted:continue
  # fallback: if equal match, else move toward larger C neighbor / smaller remaining
  if i<n and j<m and aa[i]==bb[j]:ma[i]=mb[j]=True;i+=1;j+=1
  elif j>=m:i+=1
  elif i>=n:j+=1
  elif fallback=='geA':
   if C[i+1][j]>=C[i][j+1]:i+=1
   else:j+=1
  else:
   if C[i][j+1]>=C[i+1][j]:j+=1
   else:i+=1
 return ''.join('C' if x else 'U' for x in ma[:len(a)]),''.join('C' if x else 'U' for x in mb[:len(b)])
for file in ['/tmp/lcsdata.json','/tmp/unique.json']:
 data=json.load(open(file));print(file)
 for sentinel in [1,0]:
  for order in itertools.permutations('DAB'):
   for fb in ['geA','geB']:
    fails=sum(list(walk(a,b,''.join(order),sentinel,fb))!=obs for a,b,obs in data);print(''.join(order),sentinel,fb,fails)
