import json

def scan(a,b,swap=False,cond='diag',sentinel=True):
 aa=list(b if swap else a);bb=list(a if swap else b)
 if sentinel:aa+=[None];bb+=[None]
 n,m=len(aa),len(bb);C=[[0]*(m+1) for _ in range(n+1)]
 for i in range(n):
  for j in range(m):C[i+1][j+1]=C[i][j]+1 if aa[i]==bb[j] else max(C[i][j+1],C[i+1][j])
 ma=[False]*n;mb=[False]*m;j=0
 for i in range(n):
  found=-1
  for k in range(j,m):
   if aa[i]!=bb[k]:continue
   ok=False
   if cond=='diag':ok=C[i+1][k+1]==C[i][k]+1
   elif cond=='diag_strict_neighbors':ok=C[i+1][k+1]>C[i][k] and C[i+1][k+1]>C[i+1][k] and C[i+1][k+1]>C[i][k+1]
   elif cond=='eq':ok=True
   elif cond=='inc_row':ok=C[i+1][k+1]>C[i][k+1]
   elif cond=='inc_col':ok=C[i+1][k+1]>C[i+1][k]
   if ok:found=k;break
  if found>=0:ma[i]=mb[found]=True;j=found+1
 A=''.join('C' if x else 'U' for x in ma[:len(b if swap else a)]);B=''.join('C' if x else 'U' for x in mb[:len(a if swap else b)])
 return (B,A) if swap else (A,B)
for file in ['/tmp/lcsdata.json','/tmp/unique.json']:
 data=json.load(open(file));print(file)
 for swap in [0,1]:
  for cond in ['diag','diag_strict_neighbors','eq','inc_row','inc_col']:
   fails=sum(list(scan(a,b,swap,cond))!=obs for a,b,obs in data);print(swap,cond,fails)
