import json,collections

def anchor_alg(a,b,choose='firstA',occ='first',extend=False,sentinel=True):
 aa=list(a)+([None] if sentinel else []);bb=list(b)+([None] if sentinel else [])
 ma=[False]*len(aa);mb=[False]*len(bb)
 def find_occurrences(x,j1,j2):return [j for j in range(j1,j2) if bb[j]==x]
 def find_in_a(y,i1,i2):return [i for i in range(i1,i2) if aa[i]==y]
 def rec(i1,i2,j1,j2):
  if i1>=i2 or j1>=j2:return
  pair=None
  if choose in ('firstA','lastA'):
   rng=range(i1,i2) if choose=='firstA' else range(i2-1,i1-1,-1)
   for i in rng:
    occs=find_occurrences(aa[i],j1,j2)
    if occs:pair=(i,occs[0] if occ=='first' else occs[-1]);break
  elif choose in ('firstB','lastB'):
   rng=range(j1,j2) if choose=='firstB' else range(j2-1,j1-1,-1)
   for j in rng:
    occs=find_in_a(bb[j],i1,i2)
    if occs:pair=(occs[0] if occ=='first' else occs[-1],j);break
  elif choose in ('minfreqA','maxfreqA','minfreqB','maxfreqB'):
   # choose a common token value minimizing/maximizing total occurrences in both intervals; tie by first occurrence in A or B according chooser side
   vals=[]
   freqA=collections.Counter(aa[i1:i2]);freqB=collections.Counter(bb[j1:j2])
   common=[x for x in freqA if x in freqB]
   if not common:return
   if choose.startswith('min'):best=min(freqA[x]+freqB[x] for x in common)
   else:best=max(freqA[x]+freqB[x] for x in common)
   cand=[x for x in common if freqA[x]+freqB[x]==best]
   # tie pick token whose first A occurrence is earliest (or B if side B)
   if choose.endswith('A'):x=min(cand,key=lambda x:aa.index(x,i1,i2))
   else:x=min(cand,key=lambda x:bb.index(x,j1,j2))
   i=aa.index(x,i1,i2) if occ=='first' else len(aa)-1-aa[::-1].index(x, len(aa)-i2, len(aa)-i1) if False else max(k for k in range(i1,i2) if aa[k]==x)
   # for occurrence in other side, use first/last as occ
   occs=find_occurrences(x,j1,j2);j=occs[0] if occ=='first' else occs[-1]
   # If chooser side B, i should be occ-based too; simplify: if choose endswith B, choose j first then i based occ (already i first/last)
   pair=(i,j)
  elif choose=='midA':
   # search outward from mid A for a token in B (mid,mid+1,mid-1,...)
   mid=(i1+i2)//2;order=[]
   for d in range(max(i2-mid,mid-i1)+1):
    if mid+d<i2:order.append(mid+d)
    if d and mid-d>=i1:order.append(mid-d)
   for i in order:
    occs=find_occurrences(aa[i],j1,j2)
    if occs:pair=(i,occs[0] if occ=='first' else occs[-1]);break
  if pair is None:return
  i,j=pair;left=right=0
  if extend:
   while i-left-1>=i1 and j-left-1>=j1 and aa[i-left-1]==bb[j-left-1]:left+=1
   while i+right+1<i2 and j+right+1<j2 and aa[i+right+1]==bb[j+right+1]:right+=1
  for k in range(-left,right+1):ma[i+k]=mb[j+k]=True
  rec(i1,i-left,j1,j-left);rec(i+right+1,i2,j+right+1,j2)
 rec(0,len(aa),0,len(bb))
 return ''.join('C' if x else 'U' for x in ma[:len(a)]),''.join('C' if x else 'U' for x in mb[:len(b)])
for file in ['/tmp/lcsdata.json','/tmp/unique.json']:
 data=json.load(open(file));print(file)
 for choose in ['firstA','lastA','firstB','lastB','minfreqA','maxfreqA','minfreqB','maxfreqB','midA']:
  for occ in ['first','last']:
   for ext in [False,True]:
    fails=sum(list(anchor_alg(a,b,choose,occ,ext))!=obs for a,b,obs in data);print(choose,occ,ext,fails)
