            attributes = attribute
                       | attribute + ':' + attributes
            attribute  = ('foreground' | 'background') + ':' + color
                       | (<empty> | 'no') + font-flag
                       | 'none'
            font-flag  = 'italic'
                       | 'bold'
                       | 'intense'
                       | 'underline'
            color      = 'none'
                       | [0-255]
                       | [0-255] + ',' + [0-255] + ',' + [0-255]
                       | ('black', 'blue', 'green', 'red',
                          'cyan', 'magenta', 'yellow', 'white')

            For example, the color_spec

                'refine-added:background:blue:bold'

            sets the color of unique added segments with
            a blue background, written with a bold font.

        --line-numbers <compact|aligned>
            Display line numbers. Style is optional.
            When style = 'compact', take as little width as possible.
            When style = 'aligned', align to tab stops (useful if tab is used for indentation). [default: compact]

    -h, --help
            Prints help information

    -V, --version
            Prints version information
";

// ---------------------------------------------------------------------------
// Colors / faces
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Color {
    Basic(u8), // 0 black, 1 red, 2 green, 3 yellow, 4 blue, 5 magenta, 6 cyan, 7 white
    Ansi256(u8),
    Rgb(u8, u8, u8),
}

#[derive(Clone, Copy, Debug, Default)]
struct Face {
    fg: Option<Color>,
    bg: Option<Color>,
    bold: bool,
    dimmed: bool,
    italic: bool,
    underline: bool,
    intense: bool,
}

impl Face {
    fn write_style<W: Write>(&self, out: &mut W) -> io::Result<()> {
        out.write_all(b"\x1b[0m")?;
        if self.bold {
            out.write_all(b"\x1b[1m")?;
        }
        if self.dimmed {
            out.write_all(b"\x1b[2m")?;
        }
        if self.italic {
            out.write_all(b"\x1b[3m")?;
        }
        if self.underline {
            out.write_all(b"\x1b[4m")?;
        }
        if let Some(c) = self.fg {
            write_color(out, c, true, self.intense)?;
        }
        if let Some(c) = self.bg {
            write_color(out, c, false, self.intense)?;
        }
        Ok(())
    }
}

fn write_color<W: Write>(out: &mut W, color: Color, fg: bool, intense: bool) -> io::Result<()> {
    match color {
        Color::Basic(idx) => {
            if intense {
                if fg {
                    write!(out, "\x1b[38;5;{}m", 8 + idx)
                } else {
                    write!(out, "\x1b[48;5;{}m", 8 + idx)
                }
            } else if fg {
                write!(out, "\x1b[{}m", 30 + idx)
            } else {
                write!(out, "\x1b[{}m", 40 + idx)
            }
        }
        Color::Ansi256(n) => {
            if fg {
                write!(out, "\x1b[38;5;{}m", n)
            } else {
                write!(out, "\x1b[48;5;{}m", n)
            }
        }
        Color::Rgb(r, g, b) => {
            if fg {
                write!(out, "\x1b[38;2;{};{};{}m", r, g, b)
            } else {
                write!(out, "\x1b[48;2;{};{};{}m", r, g, b)
            }
        }
    }
}

const FACE_ADDED: usize = 0;
const FACE_REFINE_ADDED: usize = 1;
const FACE_REMOVED: usize = 2;
const FACE_REFINE_REMOVED: usize = 3;

fn default_faces() -> [Face; 4] {
    let mut added = Face::default();
    added.fg = Some(Color::Basic(2));
    let mut removed = Face::default();
    removed.fg = Some(Color::Basic(1));
    let mut refine_added = Face::default();
    refine_added.fg = Some(Color::Rgb(255, 255, 255));
    refine_added.bg = Some(Color::Basic(2));
    refine_added.bold = true;
    let mut refine_removed = Face::default();
    refine_removed.fg = Some(Color::Rgb(255, 255, 255));
    refine_removed.bg = Some(Color::Basic(1));
    refine_removed.bold = true;
    [added, refine_added, removed, refine_removed]
}

fn bg_red_face() -> Face {
    let mut f = Face::default();
    f.bg = Some(Color::Basic(1));
    f
}

fn parse_byte(s: &str) -> Option<u8> {
    if let Some(hex) = s.strip_prefix("0x") {
        if hex.is_empty() {
            return None;
        }
        u8::from_str_radix(hex, 16).ok()
    } else {
        s.parse::<u8>().ok()
    }
}

fn parse_color(s: &str) -> Result<Option<Color>, String> {
    if s == "none" {
        return Ok(None);
    }
    if s.contains(',') {
        let parts: Vec<&str> = s.split(',').collect();
        let rgb_err = || {
            format!(
                "unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'",
                s
            )
        };
        if parts.len() != 3 {
            return Err(rgb_err());
        }
        let mut vals = [0u8; 3];
        for (i, p) in parts.iter().enumerate() {
            match parse_byte(p) {
                Some(v) => vals[i] = v,
                None => return Err(rgb_err()),
            }
        }
        return Ok(Some(Color::Rgb(vals[0], vals[1], vals[2])));
    }
    // Named colors are matched case-insensitively (ASCII).
    let lower = s.to_ascii_lowercase();
    let basic = match lower.as_str() {
        "black" => Some(0),
        "blue" => Some(4),
        "green" => Some(2),
        "red" => Some(1),
        "cyan" => Some(6),
        "magenta" => Some(5),
        "yellow" => Some(3),
        "white" => Some(7),
        _ => None,
    };
    if let Some(idx) = basic {
        return Ok(Some(Color::Basic(idx)));
    }
    if let Some(n) = parse_byte(s) {
        return Ok(Some(Color::Ansi256(n)));
    }
    if s.chars().all(|c| c.is_ascii_hexdigit()) {
        Err(format!(
            "unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'",
            s
        ))
    } else {
        Err(format!(
            "unexpected color value: unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white",
            s
        ))
    }
}

fn parse_color_spec(spec: &str, faces: &mut [Face; 4]) -> Result<(), String> {
    let mut it = spec.split(':');
    let face_name = it.next().unwrap_or("");
    let face_idx = match face_name {
        "added" => FACE_ADDED,
        "refine-added" => FACE_REFINE_ADDED,
        "removed" => FACE_REMOVED,
        "refine-removed" => FACE_REFINE_REMOVED,
        _ => {
            return Err(format!(
                "unexpected face name: got '{}', expected added|refine-added|removed|refine-removed",
                face_name
            ))
        }
    };
    let face = &mut faces[face_idx];
    while let Some(attr) = it.next() {
        match attr {
            "foreground" | "background" => {
                let val = match it.next() {
                    Some(v) => v,
                    None => {
                        return Err(format!(
                            "error parsing color: missing color value for face '{}'",
                            face_name
                        ))
                    }
                };
                let color = parse_color(val)?;
                if attr == "foreground" {
                    face.fg = color;
                } else {
                    face.bg = color;
                }
            }
            "italic" => face.italic = true,
            "noitalic" => face.italic = false,
            "bold" => face.bold = true,
            "nobold" => face.bold = false,
            "dimmed" => face.dimmed = true,
            "nodimmed" => face.dimmed = false,
            "intense" => face.intense = true,
            "nointense" => face.intense = false,
            "underline" => face.underline = true,
            "nounderline" => face.underline = false,
            "none" => *face = Face::default(),
            _ => {
                return Err(format!(
                    "unexpected attribute name: got '{}', expected foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none",
                    attr
                ))
            }
        }
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// Line numbers
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum LnStyle {
    Compact,
    Aligned,
    Fixed,
}

fn digits0(mut n: usize) -> usize {
    if n == 0 {
        return 0;
    }
    let mut d = 0;
    while n > 0 {
        d += 1;
        n /= 10;
    }
    d
}
fn digits1(n: usize) -> usize {
    let d = digits0(n);
    if d == 0 {
        1
    } else {
        d
    }
}
fn decimal_len(n: usize) -> usize {
    digits1(n)
}

#[derive(Clone, Debug)]
struct LnState {
    parsed: bool,
    old_start: usize,
    old_len: usize,
    new_start: usize,
    new_len: usize,
    old_cur: usize,
    new_cur: usize,
    old_active: bool,
    new_active: bool,
    style: LnStyle,
    width_refined: usize,
    width_context: usize,
}

impl LnState {
    fn default_malformed() -> Self {
        LnState {
            parsed: false,
            old_start: 0,
            old_len: 0,
            new_start: 0,
            new_len: 0,
            old_cur: 0,
            new_cur: 0,
            old_active: false,
            new_active: false,
            style: LnStyle::Compact,
            width_refined: 0,
            width_context: 1,
        }
    }
    fn new(parsed: bool, os: usize, ol: usize, ns: usize, nl: usize, style: LnStyle) -> Self {
        if !parsed {
            return Self::default_malformed();
        }
        let max_stop = std::cmp::max(os.wrapping_add(ol), ns.wrapping_add(nl));
        let w0 = digits0(max_stop);
        let w1 = digits1(max_stop);
        let (width_refined, width_context) = match style {
            LnStyle::Fixed => (std::cmp::max(3, w0), std::cmp::max(3, w1)),
            _ => (w0, w1),
        };
        LnState {
            parsed: true,
            old_start: os,
            old_len: ol,
            new_start: ns,
            new_len: nl,
            old_cur: os,
            new_cur: ns,
            old_active: os != 0,
            new_active: ns != 0,
            style,
            width_refined,
            width_context,
        }
    }

    fn format_context(&self) -> String {
        let w = self.width_context;
        let mut s = if self.old_cur == self.new_cur {
            format!("{:>width$}", self.old_cur, width = 2 * w + 1)
        } else {
            format!("{:>w$} {:>w$}", self.old_cur, self.new_cur, w = w)
        };
        if self.style == LnStyle::Aligned {
            // Observed special case: a successfully parsed header with both
            // ranges exactly 0,0 produces no tab for a context line.
            let both_zero_ranges =
                self.parsed && self.old_start == 0 && self.old_len == 0 && self.new_start == 0 && self.new_len == 0;
            if !both_zero_ranges {
                s.push('\t');
            }
        }
        s
    }

    fn format_refined(&self, is_minus: bool) -> io::Result<String> {
        let own = if is_minus { self.old_cur } else { self.new_cur };
        let other_active = if is_minus { self.new_active } else { self.old_active };
        let w = self.width_refined;
        if !other_active {
            if decimal_len(own) > w {
                return Err(io::Error::from(io::ErrorKind::WriteZero));
            }
            Ok(format!("{:>w$}", own, w = w))
        } else {
            if self.old_start == 0 || self.new_start == 0 {
                return Err(io::Error::from(io::ErrorKind::WriteZero));
            }
            if decimal_len(own) > w {
                return Err(io::Error::from(io::ErrorKind::WriteZero));
            }
            if is_minus {
                Ok(format!("{:>w$} {:w$}", own, "", w = w))
            } else {
                Ok(format!("{:w$} {:>w$}", "", own, w = w))
            }
        }
    }
}

fn split_ascii_whitespace(bytes: &[u8]) -> Vec<&[u8]> {
    let mut out = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        while i < bytes.len() && bytes[i].is_ascii_whitespace() {
            i += 1;
        }
        if i >= bytes.len() {
            break;
        }
        let start = i;
        while i < bytes.len() && !bytes[i].is_ascii_whitespace() {
            i += 1;
        }
        out.push(&bytes[start..i]);
    }
    out
}

fn parse_decimal_token(s: &[u8]) -> Option<usize> {
    if s.is_empty() || !s.iter().all(|b| b.is_ascii_digit()) {
        return None;
    }
    // All digits; use Rust parsing for overflow behaviour.
    std::str::from_utf8(s).ok()?.parse::<usize>().ok()
}

fn parse_range_token(tok: &[u8], sign: u8) -> Option<(usize, usize)> {
    if tok.len() < 2 || tok[0] != sign {
        return None;
    }
    let rest = &tok[1..];
    let mut parts = rest.split(|b| *b == b',');
    let first = parts.next()?;
    let start = parse_decimal_token(first)?;
    let len = match parts.next() {
        Some(p) => parse_decimal_token(p)?,
        None => 1,
    };
    if parts.next().is_some() {
        return None;
    }
    Some((start, len))
}

fn parse_hunk_header(raw: &[u8], style: LnStyle) -> LnState {
    let tokens = split_ascii_whitespace(raw);
    let parsed = parse_hunk_header_inner(&tokens);
    match parsed {
        Some((os, ol, ns, nl)) => LnState::new(true, os, ol, ns, nl, style),
        None => LnState::default_malformed(),
    }
}

fn parse_hunk_header_inner(tokens: &[&[u8]]) -> Option<(usize, usize, usize, usize)> {
    let mut idx = 0usize;
    let first = *tokens.get(idx)?;
    if first.is_empty() || !first.iter().all(|b| *b == b'@') {
        return None;
    }
    idx += 1;
    // One or more minus ranges; the last one wins.
    let mut minus: Option<(usize, usize)> = None;
    while let Some(tok) = tokens.get(idx) {
        if tok.first() == Some(&b'-') {
            minus = Some(parse_range_token(tok, b'-')?);
            idx += 1;
        } else {
            break;
        }
    }
    let minus = minus?;
    let plus_tok = *tokens.get(idx)?;
    if plus_tok.first() != Some(&b'+') {
        return None;
    }
    let plus = parse_range_token(plus_tok, b'+')?;
    idx += 1;
    let closing = *tokens.get(idx)?;
    if closing.first() != Some(&b'@') {
        return None;
    }
    Some((minus.0, minus.1, plus.0, plus.1))
}

// ---------------------------------------------------------------------------
// Tokenisation
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum UnitKind {
    Word,
    Space,
    Other,
}

#[derive(Clone, Copy, Debug)]
struct Unit {
    start: usize,
    end: usize,
    kind: UnitKind,
}

fn decode_units(bytes: &[u8]) -> Vec<Unit> {
    let mut units = Vec::new();
    let mut i = 0usize;
    while i < bytes.len() {
        match std::str::from_utf8(&bytes[i..]) {
            Ok(s) => {
                for (off, ch) in s.char_indices() {
                    let start = i + off;
                    let end = start + ch.len_utf8();
                    let kind = if ch.is_alphanumeric() || ch == '_' {
                        UnitKind::Word
                    } else if ch == ' ' || ch == '\t' {
                        UnitKind::Space
                    } else {
                        UnitKind::Other
                    };
                    units.push(Unit { start, end, kind });
                }
                break;
            }
            Err(e) => {
                let valid = e.valid_up_to();
                if valid > 0 {
                    let s = std::str::from_utf8(&bytes[i..i + valid]).unwrap();
                    for (off, ch) in s.char_indices() {
                        let start = i + off;
                        let end = start + ch.len_utf8();
                        let kind = if ch.is_alphanumeric() || ch == '_' {
                            UnitKind::Word
                        } else if ch == ' ' || ch == '\t' {
                            UnitKind::Space
                        } else {
                            UnitKind::Other
                        };
                        units.push(Unit { start, end, kind });
                    }
                    i += valid;
                    continue;
                }
                // Invalid byte: treat a single byte as an "other" unit.
                units.push(Unit {
                    start: i,
                    end: i + 1,
                    kind: UnitKind::Other,
                });
                i += 1;
            }
        }
    }
    units
}

#[derive(Clone, Debug)]
struct Token {
    line_idx: usize,
    start: usize, // byte offset in the raw line (without newline)
    end: usize,
    value: Vec<u8>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum LineKind {
    Context,
    Minus,
    Plus,
    Backslash,
}

#[derive(Clone, Debug)]
struct HunkLine {
    raw: Vec<u8>, // without trailing '\n'
    has_nl: bool,
    kind: LineKind,
    prefix_end: usize,
    tokenless: bool,
}

fn analyse_line(raw: &[u8], kind: LineKind) -> (usize, bool) {
    if kind != LineKind::Minus && kind != LineKind::Plus {
        return (0, false);
    }
    // Find first byte after the sign that is not ASCII whitespace.
    let mut pos: Option<usize> = None;
    for i in 1..raw.len() {
        if !raw[i].is_ascii_whitespace() {
            pos = Some(i);
            break;
        }
    }
    match pos {
        Some(p) => (p, false),
        None => (1.min(raw.len()), true),
    }
}

fn tokenise_line(line_idx: usize, line: &HunkLine) -> Vec<Token> {
    if line.tokenless {
        return Vec::new();
    }
    let content_start = line.prefix_end;
    let content = &line.raw[content_start..];
    let units = decode_units(content);
    let mut tokens = Vec::new();
    let mut u = 0usize;
    while u < units.len() {
        let kind = units[u].kind;
        let start_unit = u;
        match kind {
            UnitKind::Word | UnitKind::Space => {
                while u < units.len() && units[u].kind == kind {
                    u += 1;
                }
            }
            UnitKind::Other => {
                u += 1;
            }
        }
        let start = content_start + units[start_unit].start;
        let end = content_start + units[u - 1].end;
        tokens.push(Token {
            line_idx,
            start,
            end,
            value: line.raw[start..end].to_vec(),
        });
    }
    if line.has_nl {
        tokens.push(Token {
            line_idx,
            start: line.raw.len(),
            end: line.raw.len(),
            value: b"\n".to_vec(),
        });
    }
    tokens
}

// ---------------------------------------------------------------------------
// LCS (dynamic programming table, read out by moving up/left when the
// table value is unchanged)
// ---------------------------------------------------------------------------

fn compute_matched(minus: &[Token], plus: &[Token]) -> (Vec<bool>, Vec<bool>) {
    let n = minus.len();
    let m = plus.len();
    let mut ma = vec![false; n];
    let mut mb = vec![false; m];
    if n == 0 || m == 0 {
        return (ma, mb);
    }
    // Safety guard against absurd table sizes.
    if (n as u128) * (m as u128) > 100_000_000 {
        return (ma, mb);
    }
    // Flat table (n+1) x (m+1).
    let width = m + 1;
    let mut table = vec![0u32; (n + 1) * width];
    let idx = |i: usize, j: usize| i * width + j;
    for i in 0..n {
        for j in 0..m {
            let v = if minus[i].value == plus[j].value {
                table[idx(i, j)] + 1
            } else {
                std::cmp::max(table[idx(i, j + 1)], table[idx(i + 1, j)])
            };
            let t = idx(i + 1, j + 1);
            table[t] = v;
        }
    }
    let mut i = n;
    let mut j = m;
    while i > 0 && j > 0 {
        if table[idx(i, j)] == table[idx(i - 1, j)] {
            i -= 1;
        } else if table[idx(i, j)] == table[idx(i, j - 1)] {
            j -= 1;
        } else {
            // Diagonal step: these tokens are part of an LCS.
            ma[i - 1] = true;
            mb[j - 1] = true;
            i -= 1;
            j -= 1;
        }
    }
    (ma, mb)
}

// ---------------------------------------------------------------------------
// Output helpers
// ---------------------------------------------------------------------------

fn write_styled<W: Write>(out: &mut W, face: &Face, text: &[u8]) -> io::Result<()> {
    face.write_style(out)?;
    out.write_all(text)?;
    out.write_all(b"\x1b[0m")
}

fn write_plain_line<W: Write>(out: &mut W, raw: &[u8], has_nl: bool) -> io::Result<()> {
    out.write_all(b"\x1b[0m")?;
    out.write_all(raw)?;
    out.write_all(b"\x1b[0m")?;
    if has_nl {
        out.write_all(b"\n")?;
    }
    Ok(())
}

struct Config {
    faces: [Face; 4],
    line_numbers: Option<LnStyle>,
}

fn flush_hunk<W: Write>(
    out: &mut W,
    lines: &[HunkLine],
    ln: &mut LnState,
    cfg: &Config,
) -> io::Result<()> {
    if lines.is_empty() {
        return Ok(());
    }
    // Build token lists per side.
    let mut minus_tokens: Vec<Token> = Vec::new();
    let mut plus_tokens: Vec<Token> = Vec::new();
    // For each line, remember (start,end) indices into its side token vec.
    let mut minus_ranges: Vec<(usize, usize)> = vec![(0, 0); lines.len()];
    let mut plus_ranges: Vec<(usize, usize)> = vec![(0, 0); lines.len()];
    for (idx, line) in lines.iter().enumerate() {
        match line.kind {
            LineKind::Minus => {
                let start = minus_tokens.len();
                minus_tokens.extend(tokenise_line(idx, line));
                minus_ranges[idx] = (start, minus_tokens.len());
            }
            LineKind::Plus => {
                let start = plus_tokens.len();
                plus_tokens.extend(tokenise_line(idx, line));
                plus_ranges[idx] = (start, plus_tokens.len());
            }
            _ => {}
        }
    }
    // Token-count guard observed in the original for very large hunks in
    // cases with few common tokens.  Keep a high guard only to avoid
    // pathological table sizes; compute_matched has its own guard.
    let (minus_matched, plus_matched) = compute_matched(&minus_tokens, &plus_tokens);

    for (idx, line) in lines.iter().enumerate() {
        match line.kind {
            LineKind::Context => {
                if cfg.line_numbers.is_some() {
                    let field = ln.format_context();
                    out.write_all(field.as_bytes())?;
                    write_plain_line_after_number(out, line)?;
                } else {
                    write_plain_line(out, &line.raw, line.has_nl)?;
                }
                ln.old_cur = ln.old_cur.wrapping_add(1);
                ln.new_cur = ln.new_cur.wrapping_add(1);
                ln.old_active = true;
                ln.new_active = true;
            }
            LineKind::Backslash => {
                write_plain_line(out, &line.raw, line.has_nl)?;
            }
            LineKind::Minus | LineKind::Plus => {
                let is_minus = line.kind == LineKind::Minus;
                let face = if is_minus {
                    cfg.faces[FACE_REMOVED]
                } else {
                    cfg.faces[FACE_ADDED]
                };
                let refine = if is_minus {
                    cfg.faces[FACE_REFINE_REMOVED]
                } else {
                    cfg.faces[FACE_REFINE_ADDED]
                };
                // Line number field is computed before writing anything of
                // this line; a formatting error aborts the whole run.
                let number_field = if cfg.line_numbers.is_some() {
                    Some(ln.format_refined(is_minus)?)
                } else {
                    None
                };
                if let Some(field) = number_field {
                    write_styled(out, &face, field.as_bytes())?;
                    if ln.style == LnStyle::Aligned && cfg.line_numbers == Some(LnStyle::Aligned) {
                        out.write_all(b"\t")?;
                    }
                }
                // Prefix segment (sign + leading ASCII whitespace, or just sign).
                let prefix = &line.raw[..line.prefix_end];
                write_styled(out, &face, prefix)?;
                if line.tokenless {
                    let rest = if line.raw.len() > 1 { &line.raw[1..] } else { &[][..] };
                    write_styled(out, &bg_red_face(), rest)?;
                } else {
                    let (tokens, matched, range) = if is_minus {
                        (&minus_tokens, &minus_matched, minus_ranges[idx])
                    } else {
                        (&plus_tokens, &plus_matched, plus_ranges[idx])
                    };
                    // Group consecutive tokens by matched flag.
                    let mut t = range.0;
                    while t < range.1 {
                        let is_match = matched[t];
                        let group_start = tokens[t].start;
                        let mut group_end = tokens[t].end;
                        t += 1;
                        while t < range.1 && matched[t] == is_match {
                            group_end = tokens[t].end;
                            t += 1;
                        }
                        let text = &line.raw[group_start..group_end];
                        let style = if is_match { &face } else { &refine };
                        write_styled(out, style, text)?;
                    }
                }
                if line.has_nl {
                    out.write_all(b"\n")?;
                }
                if is_minus {
                    ln.old_cur = ln.old_cur.wrapping_add(1);
                    ln.old_active = true;
                } else {
                    ln.new_cur = ln.new_cur.wrapping_add(1);
                    ln.new_active = true;
                }
            }
        }
    }
    Ok(())
}

fn write_plain_line_after_number<W: Write>(out: &mut W, line: &HunkLine) -> io::Result<()> {
    // Context line with line numbers: number already written, then the same
    // styled body as a plain line (reset, text, reset, newline).
    out.write_all(b"\x1b[0m")?;
    out.write_all(&line.raw)?;
    out.write_all(b"\x1b[0m")?;
    if line.has_nl {
        out.write_all(b"\n")?;
    }
    Ok(())
}

fn run<W: Write>(out: &mut W, cfg: &Config) -> io::Result<()> {
    let stdin = io::stdin();
    let mut reader = io::BufReader::new(stdin.lock());
    let default_style = cfg.line_numbers.unwrap_or(LnStyle::Compact);
    let mut ln = LnState::new(false, 0, 0, 0, 0, default_style);
    let mut in_hunk = false;
    let mut hunk_lines: Vec<HunkLine> = Vec::new();

    let mut buf: Vec<u8> = Vec::new();
    loop {
        buf.clear();
        let n = reader.read_until(b'\n', &mut buf)?;
        if n == 0 {
            break;
        }
        let has_nl = buf.last() == Some(&b'\n');
        let raw: Vec<u8> = if has_nl {
            buf[..buf.len() - 1].to_vec()
        } else {
            buf.clone()
        };
        let first = raw.first().copied();
        if first == Some(b'@') {
            if in_hunk {
                flush_hunk(out, &hunk_lines, &mut ln, cfg)?;
                hunk_lines.clear();
            }
            ln = parse_hunk_header(&raw, default_style);
            in_hunk = true;
            write_plain_line(out, &raw, has_nl)?;
            continue;
        }
        if in_hunk {
            match first {
                Some(b' ') => {
                    hunk_lines.push(HunkLine {
                        raw,
                        has_nl,
                        kind: LineKind::Context,
                        prefix_end: 0,
                        tokenless: false,
                    });
                }
                Some(b'-') => {
                    let (pfx, tokenless) = analyse_line(&raw, LineKind::Minus);
                    hunk_lines.push(HunkLine {
                        raw,
                        has_nl,
                        kind: LineKind::Minus,
                        prefix_end: pfx,
                        tokenless,
                    });
                }
                Some(b'+') => {
                    let (pfx, tokenless) = analyse_line(&raw, LineKind::Plus);
                    hunk_lines.push(HunkLine {
                        raw,
                        has_nl,
                        kind: LineKind::Plus,
                        prefix_end: pfx,
                        tokenless,
                    });
                }
                Some(b'\\') => {
                    hunk_lines.push(HunkLine {
                        raw,
                        has_nl,
                        kind: LineKind::Backslash,
                        prefix_end: 0,
                        tokenless: false,
                    });
                }
                _ => {
                    flush_hunk(out, &hunk_lines, &mut ln, cfg)?;
                    hunk_lines.clear();
                    in_hunk = false;
                    write_plain_line(out, &raw, has_nl)?;
                }
            }
        } else {
            write_plain_line(out, &raw, has_nl)?;
        }
    }
    if in_hunk {
        flush_hunk(out, &hunk_lines, &mut ln, cfg)?;
    }
    out.flush()?;
    Ok(())
}

fn main() {
    // Long help takes precedence over everything else.  Using
    // env::args().any(..) intentionally mirrors the lazy iterator
    // behaviour for invalid UTF-8 arguments.
    if env::args().any(|a| a == "--help") {
        let _ = write!(io::stdout().lock(), "{}", LONG_HELP);
        return;
    }

    let mut faces = default_faces();
    let mut line_numbers: Option<LnStyle> = None;
    let mut args = env::args();
    let _ = args.next();
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "-h" => {
                let _ = write!(io::stdout().lock(), "{}", SHORT_HELP);
                return;
            }
            "-V" | "--version" => {
                eprintln!("diffr {}", VERSION);
                return;
            }
            "--colors" => {
                let spec = match args.next() {
                    Some(s) => s,
                    None => {
                        eprintln!("option requires an argument: '--colors'");
                        process::exit(2);
                    }
                };
                if let Err(e) = parse_color_spec(&spec, &mut faces) {
                    eprintln!("{}", e);
                    process::exit(-1);
                }
            }
            "--line-numbers" => {
                let style = match args.next() {
                    None => LnStyle::Compact,
                    Some(s) => match s.as_str() {
                        "compact" => LnStyle::Compact,
                        "aligned" => LnStyle::Aligned,
                        "fixed" => LnStyle::Fixed,
                        _ => {
                            eprintln!(
                                "unexpected line number style: got '{}', expected aligned|compact|fixed",
                                s
                            );
                            process::exit(-1);
                        }
                    },
                };
                line_numbers = Some(style);
            }
            _ => {
                eprint!("bad argument: '{}'\n{}", arg, SHORT_HELP);
                process::exit(2);
            }
        }
    }

    let cfg = Config {
        faces,
        line_numbers,
    };
    let stdout = io::stdout();
    let mut lock = stdout.lock();
    match run(&mut lock, &cfg) {
        Ok(()) => {}
        Err(e) => {
            if e.kind() == io::ErrorKind::BrokenPipe {
                return;
            }
            // Best effort flush of anything already buffered, then report.
            let _ = lock.flush();
            eprintln!("io error: {}", e);
            process::exit(-1);
        }
    }
}
