import json,sys
sys.path.insert(0,'/tmp')

def lookahead(a,b,K=1,tie='A',nomatch='both',sentinel=True):
 aa=list(a)+([None] if sentinel else []);bb=list(b)+([None] if sentinel else []);n=len(aa);m=len(bb);ma=[False]*n;mb=[False]*m;i=j=0
 def find(arr,start,x,limit):
  for d in range(1,limit+1):
   if start+d < len(arr) and arr[start+d]==x:return d
  return None
 while i<n and j<m:
  if aa[i]==bb[j]:ma[i]=mb[j]=True;i+=1;j+=1;continue
  limit = K if K is not None else max(n,m)
  da=find(aa,i,bb[j],limit)  # skip da in A to match B token
  db=find(bb,j,aa[i],limit)  # skip db in B to match A token
  if da is not None and db is not None:
   if da<db or (da==db and tie=='A'):i+=da
   else:j+=db
  elif da is not None:i+=da
  elif db is not None:j+=db
  else:
   if nomatch=='both':i+=1;j+=1
   elif nomatch=='A':i+=1
